describe('Image Upload Preview', () => {
  beforeEach(() => {
    cy.visit('/upload');
  });

  it('should display image preview after uploading a valid image', () => {
    // Intercept the file upload API
    cy.intercept('POST', '/api/upload').as('uploadImage');

    // Upload a valid image file
    cy.get('[data-testid="image-upload-input"]').selectFile('cypress/fixtures/sample-image.png', { force: true });

    // Wait for the upload API call
    cy.wait('@uploadImage');

    // Verify preview image is displayed
    cy.get('[data-testid="image-preview-container"]').should('be.visible');
    cy.get('[data-testid="preview-image"]').should('be.visible');
    cy.get('[data-testid="preview-image"]').should('have.attr', 'src');

    // Verify preview has correct dimensions
    cy.get('[data-testid="preview-image"]').should('have.css', 'width', '100px');
    cy.get('[data-testid="preview-image"]').should('have.css', 'height', '100px');

    // Verify preview container has correct class
    cy.get('[data-testid="image-preview-container"]').should('have.class', 'image-preview');

    // Verify submit button is enabled
    cy.get('[data-testid="submit-button"]').should('not.be.disabled');
  });

  it('should not display preview when uploading an invalid file type', () => {
    // Intercept the upload API
    cy.intercept('POST', '/api/upload').as('uploadImage');

    // Attempt to upload an invalid file type (e.g., .txt)
    cy.get('[data-testid="image-upload-input"]').selectFile('cypress/fixtures/sample.txt', { force: true });

    // Wait for the upload API call
    cy.wait('@uploadImage');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid file type');

    // Verify preview is not displayed
    cy.get('[data-testid="image-preview-container"]').should('not.exist');

    // Verify submit button is disabled
    cy.get('[data-testid="submit-button"]').should('be.disabled');

    // Verify error icon is visible
    cy.get('[data-testid="error-icon"]').should('be.visible');
  });
});
